/*!
 * \file
 * \brief Defines the compiled Bi-213 marginal source-emission laws.
 *
 * LNHB: H. Xiaolong and W. Baosong, CNDC, 2011; 2013 tables and 2021 atomic
 * update. Selected beta-minus/alpha source emissions.
 *
 * BetaShape 2.4 (06/2024): calculated transition shapes. Conditional bin
 * masses integrate piecewise-linear reference densities; full-support
 * references and finite grids remain distinct.
 *
 * Retained forbidden-transition approximations are selected numerical laws,
 * not experimental shape validation.
 *
 * Alpha lines describe direct parent decay only; radioactive daughter alpha
 * decay is excluded.
 *
 * M and N+O yields for two transitions use table ICCs times absolute
 * gamma intensities; discrepant PenNuc exponents are not selected.
 *
 * Physical yields remain independent emissions per parent decay. EC creates
 * no primary; daughter chains and unsupported Auger energy laws are
 * excluded.
 *
 * Selection and exclusions:
 * validation/radioactivity/data/Bi-213/reference/.
 *
 * \author Julien BERT <julien.bert@univ-brest.fr>
 * \author Didier BENOIT <didier.benoit@inserm.fr>
 */

