[[nodiscard]] auto BuildBi213Radionuclide() -> GGEMSRadionuclideDefinition {
  std::vector<GGEMSRadionuclideEmission> emissions;
  emissions.reserve(17U);

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_95_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_95_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_95_keV_bin_width_micro_eV,
      },
      k_beta_minus_95_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_304_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_304_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_304_keV_bin_width_micro_eV,
      },
      k_beta_minus_304_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_323_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_323_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_323_keV_bin_width_micro_eV,
      },
      k_beta_minus_323_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_377_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_377_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_377_keV_bin_width_micro_eV,
      },
      k_beta_minus_377_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_419_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_419_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_419_keV_bin_width_micro_eV,
      },
      k_beta_minus_419_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_555_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_555_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_555_keV_bin_width_micro_eV,
      },
      k_beta_minus_555_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_822_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_822_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_822_keV_bin_width_micro_eV,
      },
      k_beta_minus_822_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_983_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_983_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_983_keV_bin_width_micro_eV,
      },
      k_beta_minus_983_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_1130_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_1130_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_1130_keV_bin_width_micro_eV,
      },
      k_beta_minus_1130_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_1423_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_1423_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_1423_keV_bin_width_micro_eV,
      },
      k_beta_minus_1423_keV_weights));

  emissions.emplace_back(particles::GGEMSParticleType::Alpha, k_alpha_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_alpha_energies_micro_eV, k_alpha_line_yields));

  emissions.emplace_back(
    particles::GGEMSParticleType::Gamma, k_nuclear_gamma_yield,
    sources::GGEMSEnergyDistribution::BuildDiscreteLines(
      k_nuclear_gamma_energies_micro_eV, k_nuclear_gamma_line_yields));

  emissions.emplace_back(
    particles::GGEMSParticleType::Gamma, k_atomic_xray_yield,
    sources::GGEMSEnergyDistribution::BuildDiscreteLines(
      k_atomic_xray_energies_micro_eV, k_atomic_xray_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_147_7_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_147_7_keV_energies_micro_eV,
                           k_conversion_147_7_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_292_8_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_292_8_keV_energies_micro_eV,
                           k_conversion_292_8_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_323_7_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_323_7_keV_energies_micro_eV,
                           k_conversion_323_7_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_440_44_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_440_44_keV_energies_micro_eV,
                           k_conversion_440_44_keV_line_yields));

  return {"Bi-213", k_half_life_seconds, std::move(emissions)};
}

